def metrics(r):
 warm=[x for x in r['runs'] if x['kind']!='primer'];res=[x['resources'] for x in warm]
 return {'average_busy_cores_median':statistics.median(x['average_busy_cores_in_monitor_window'] for x in res),'container_peak_gib':max(x['memory_current_peak_bytes'] for x in res)/GIB,'container_anon_peak_gib':max(x['memory_anon_peak_bytes'] for x in res)/GIB,'container_file_peak_gib':max(x['memory_file_peak_bytes'] for x in res)/GIB,'container_shmem_peak_gib':max(x['memory_shmem_peak_bytes'] for x in res)/GIB,'shared_read_gb_median':statistics.median(x['plan']['Plan'].get('Shared Read Blocks',0)*8192/1e9 for x in warm),'temp_written_gb_median':statistics.median(x['plan']['Plan'].get('Temp Written Blocks',0)*8192/1e9 for x in warm),'max_workers_launched_in_any_gather':max((n.get('Workers Launched',0) for x in warm for n in nodes(x['plan']['Plan'])),default=0),'client_median_seconds':statistics.median(x['client_seconds'] for x in warm),'planning_median_seconds':statistics.median(x['planning_seconds'] for x in warm),'short_query_cpu_caution':r['median_seconds']<.1}
def main():
 allsummary={};lines=['# PostgreSQL local OpenAlex benchmark','', 'Recorded 8 November 2026. This compares stock PostgreSQL query execution against the already recorded ClickHouse and Athena setups, using the same historical input files and the same selected analytical fields. No EC2 instance was launched. This starter pass measured 2.00m and 10.11m Works; 31.89m Works and the full corpus were not run in PostgreSQL.','', '## Environment and timing method','', '- Laptop: 18 CPU cores, 128 GiB RAM. Docker Desktop ARM64 VM: 16 CPUs, approximately 47 GiB RAM. Existing background containers were preserved; this is a shared laptop, not a dedicated laboratory host.','- PostgreSQL 18.6, official ARM64 `postgres:18` image, container cap **16 CPUs / 32 GiB**, shared buffers **8 GiB**, work memory **128 MiB**, up to 8 parallel workers per Gather and 16 globally. Actual worker use depends on the plan. Logged tables, fsync, full-page writes and synchronous commit remain enabled. Exact effective settings and image digest are archived.','- Data uses a dedicated **host bind mount** because the Docker VM had only 8.1 GB free. The host had 411 GiB available before loading. No unrelated containers were stopped and the VM configuration was not changed. VirtioFS and host caching influence I/O; these results cannot be transferred directly to native Linux EC2 storage.','- One primer followed by **three warm runs per case**. PostgreSQL timings are native `Execution Time` from `EXPLAIN (ANALYZE, BUFFERS, WAL, SETTINGS, TIMING OFF, FORMAT JSON)`, so per-node timer overhead is disabled. Planning and client wall times are recorded separately. EXPLAIN still adds instrumentation; its execution time is not an exact equivalent of ClickHouse query-log time or Athena service time.','- A separate complete result fetch is canonicalized using the existing typed multiset oracle. Each of the 11 cases per cohort must match its recorded row count and SHA256. Three fixed seeds are used for each graph family; summary rows report the largest seed median. Each engine can have a different worst seed.','- SQL uses the archived ClickHouse query body, preserving its ordering and limits, with standard PostgreSQL syntax (`count(*)`, `count(DISTINCT ...)`) and local table qualifiers. Athena used logically equivalent queries, some without a final full-result ordering. Historical local ClickHouse used five warm repeats; its OCI image differs from the new runs. These are comparisons of measured setups, not isolated engine or hardware effects.','', '## Query results','', '| Works | Query | PostgreSQL warm median s | PostgreSQL warm min–max s | Historical local ClickHouse s | EC2 ClickHouse s | Athena s | Output QA |','|---:|---|---:|---:|---:|---:|---:|---|']
 for tier in TIERS:
  folder=HERE/'results'/tier
  if not folder.exists():continue
  oracle=json.loads((ROOT/'results/aws-scaling-2026-11-06'/f'{tier}.json').read_text());cases={}
  for p in folder.glob('q*.json'):
   if any(x in p.stem for x in ('-canonical','-telemetry','-estimated','_preaggregate')):continue
   x=json.loads(p.read_text())
   if x.get('state')=='complete' and x.get('name') in oracle['cases']:cases[x['name']]=x
  if len(cases)!=11:continue
  overview=json.loads((ROOT/'results/aws-scaling-2026-11-06/visual-data.json').read_text())['tiers'][TIERS.index(tier)]
  families={}
  for q,label in FAMILIES.items():
   name=max((n for n in cases if n[:3]==q),key=lambda n:cases[n]['median_seconds']);r=cases[name];v=overview['queries'][q];families[q]={'selected_case':name,'median_seconds':r['median_seconds'],'warm_seconds':r['warm_seconds'],'qa_matched':all(x['qa']['matched'] for n,x in cases.items() if n[:3]==q),'resources':metrics(r)}
   lines.append(f"| {oracle['work_records']:,} | {q}: {label} | {r['median_seconds']:.6f} | {min(r['warm_seconds']):.6f}–{max(r['warm_seconds']):.6f} | {v['local_s']:.3f} | {v['ec2_s']:.3f} | {v['athena_s']:.3f} | MATCH |")
  allsummary[tier]={'works':oracle['work_records'],'raw_input_bytes':oracle['selected_raw_bytes'],'complete_authors':oracle['complete_author_records'],'families':families,'cases':{n:{'warm_seconds':r['warm_seconds'],'median_seconds':r['median_seconds'],'qa':r['qa'],'resources':metrics(r),'primer_seconds':r['runs'][0]['execution_seconds']} for n,r in cases.items()}}
 lines += ['', '**Warm is a measured condition, not a guarantee.** At 2.00m Works, original q03 took 80.31 s on the primer and 24.64 / 14.41 / 26.29 s on the three warm runs. No deliberate cold-cache reset was performed. The warm median meets 60 s, but its primer does not, and the spread is material.','', '## CPU, memory and I/O','', '| Works | Query / selected seed | Average busy cores, median | Container memory peak GiB | Anon peak GiB | File peak GiB | PG shared-buffer reads GB, median | PG temp writes GB, median | Max workers in any Gather |','|---:|---|---:|---:|---:|---:|---:|---:|---:|']
 for tier,s in allsummary.items():
  for q,v in s['families'].items():
   m=v['resources'];cpu='coarse' if m['short_query_cpu_caution'] else f"{m['average_busy_cores_median']:.2f}"
   lines.append(f"| {s['works']:,} | {v['selected_case']} | {cpu} | {m['container_peak_gib']:.2f} | {m['container_anon_peak_gib']:.2f} | {m['container_file_peak_gib']:.2f} | {m['shared_read_gb_median']:.3f} | {m['temp_written_gb_median']:.3f} | {m['max_workers_launched_in_any_gather']} |")
 lines += ['', 'CPU comes from container cgroup CPU deltas over the instrumented client window, including monitoring and background PostgreSQL work. It is not isolated backend CPU. Sub-100-ms queries have insufficient sampling resolution for a reliable isolated CPU estimate. Container memory includes shared buffers and caches; `file` includes shared-memory pages, so file and shmem must not be added together. Maxima of the separate categories need not be simultaneous.','', 'Shared-buffer reads are PostgreSQL cache misses, which may still be satisfied by OS or host caches; they are **not physical disk bytes**. Root EXPLAIN counters are used once, without summing descendant nodes. Temp writes indicate PostgreSQL spill activity. Cgroup block-I/O accounting can miss host bind-mount/VirtioFS operations; host disk counters are recorded separately but include unrelated host activity. No minimum disk bandwidth is inferred.','', '## Loading and storage','', 'PostgreSQL native COPY accepts text, CSV and its own binary format, not Parquet ([PostgreSQL documentation](https://www.postgresql.org/docs/18/sql-copy.html)). That does not require a custom row-by-row parser: a small witnessed DuckDB SQL projection reads the Parquet files and bulk-writes them through its PostgreSQL extension into ordinary PostgreSQL tables ([DuckDB documentation](https://duckdb.org/docs/stable/extensions/postgres)). **DuckDB only loads the data; PostgreSQL runs every benchmark query.** No intermediate full CSV was materialized.','', 'Both database designs require field selection and array/relationship normalization. ClickHouse performs that directly from Parquet in SQL. Here, DuckDB performs the same projection and PostgreSQL owns the resulting heap tables and ordinary B-tree indexes. No columnar PostgreSQL extension or foreign-data scan is used for the measured queries. An alternative documented by [pg_duckdb](https://github.com/duckdb/pg_duckdb) is to expose Parquet through PostgreSQL while DuckDB executes the analytical work. That alternative was not installed or tested here; it would answer a different engine-comparison question.','', '| Cohort | Complete Authors retained | Bulk insert seconds | Work-only bulk insert seconds | Index creation seconds, newly built | Database GB after indexing | Index GB |','|---|---:|---:|---:|---:|---:|---:|']
 for tier,s in allsummary.items():
  folder=HERE/'results'/tier;loads=[json.loads(p.read_text()) for p in (HERE/'results').glob('load-'+tier+'-*.json') if '-telemetry' not in p.name];idx=[json.loads(p.read_text()) for p in folder.glob('*.json') if p.stem in ('authors_pk','institutions_pk','sources_pk','topics_pk','works_pk','works_year_id','work_author_author_work','work_author_work_author','work_institution_institution_work_author','work_institution_work_institution','work_topic_topic_work','work_topic_work_topic','citation_edge_citing_cited','citation_edge_cited_citing')];storage=json.loads((folder/'storage-before-queries.json').read_text());total=sum(x['seconds'] for x in loads);work=sum(x['seconds'] for x in loads if x['table'] not in ('authors','institutions','sources','topics'));index=sum(x['seconds'] for x in idx);indexbytes=sum(x['indexes_bytes'] for x in storage['tables']);s['loading']={'copy_seconds':total,'work_copy_seconds':work,'index_seconds':index,'storage':storage};lines.append(f"| {s['works']:,} Works | 119,129,660 | {total:.2f} | {work:.2f} | {index:.2f} | {storage['database_bytes']/1e9:.3f} | {indexbytes/1e9:.3f} |")
 lines += ['', 'Copy times exclude setup, source-file metadata checks, post-load row-count validation, index creation and final VACUUM/ANALYZE; those phases are separately archived. Load telemetry spans the copy plus its post-load row-count/size validation. Dimensions are loaded and indexed once and retained at larger tiers; Work-derived tables are reset and bulk-loaded with indexes rebuilt. Table byte counts include PostgreSQL row/storage overhead; they are not comparable to raw Parquet bytes as a pure compression ratio. All tiers contain the same selected fields as ClickHouse, not complete OpenAlex records.','', '## q03 rewrite on unchanged resources','', '| Works | SQL | Warm seconds | Median s | Exact output |','|---:|---|---|---:|---|']
 for tier,s in allsummary.items():
  p=HERE/'results'/tier/'q03_preaggregate_authors.json'
  if p.exists():
   v=json.loads(p.read_text())
   if v.get('state')=='complete':s['q03_rewrite']={'warm_seconds':v['warm_seconds'],'median_seconds':v['median_seconds'],'qa':v['qa'],'resources':metrics(v)};lines.append(f"| {s['works']:,} | Aggregate author IDs before parameterized name lookup | {' / '.join(f'{x:.3f}' for x in v['warm_seconds'])} | {v['median_seconds']:.3f} | MATCH |")
 lines += ['', '| Works | Original control A median s | Rewrite median s | Original control B median s | Symmetric A/B control ratio | 50% reduction target |','|---:|---:|---:|---:|---:|---|']
 for tier,tdata in allsummary.items():
  pa=HERE/'results'/tier/'q03.json';pv=HERE/'results'/tier/'q03_preaggregate_authors.json';pb=HERE/'results'/tier/'q03_control_b.json'
  if pv.exists() and pb.exists():
   a=json.loads(pa.read_text());v=json.loads(pv.read_text());b=json.loads(pb.read_text())
   if all(x.get('state')=='complete' for x in (a,v,b)):
    ratio=max(a['median_seconds'],b['median_seconds'])/min(a['median_seconds'],b['median_seconds']);met=v['median_seconds']<=a['median_seconds']/2;tdata['q03_control']={'a_median_seconds':a['median_seconds'],'b_median_seconds':b['median_seconds'],'symmetric_ratio':ratio,'stable_at_1_20':ratio<=1.2,'rewrite_reduction_target_met':met};lines.append(f"| {tdata['works']:,} | {a['median_seconds']:.3f} | {v['median_seconds']:.3f} | {b['median_seconds']:.3f} | {ratio:.4f} | {'Met' if met else 'Not met'} |")
 lines += ['', 'At 10m, the rewrite improved the observed median but did not meet the prospective target of a 50% reduction. Original-SQL controls were within the declared 1.20 ratio bound; cache and order sensitivity still exist. At 2m there was no bracketed control.','', 'The baseline remains separate. For 2m Works, the prospective target was to halve the 24.643-s median, under identical resources. The observed rewrite median is 5.284 s, with the full 1,000-row output hash unchanged. It preserves COUNT DISTINCT and sum multiplicity. A parameterized name lookup occurs after author aggregation, and the inner lookup still filters unmatched authors before the final limit. The Authors primary key guarantees at most one matching name. This is a query-shape experiment, not a hardware upgrade. At 2m, the rewrite was measured later and no original-SQL control bracketed it; cache and order effects were not isolated, so the observed ratio is not a causal estimate attributable solely to SQL.','', '## Updating the dataset','', 'A production sync needs staging plus identity/version tracking. Upsert changed parent entities by OpenAlex ID, replace the changed Works’ authorship/institution/topic/outgoing-citation rows in the same transaction, and process tombstones and merged IDs explicitly. Copying new snapshot files and appending them would retain obsolete versions and relationships. The current benchmark schema does not retain `updated_date`; an incremental loader would need version/checkpoint metadata.','', 'The local probe stages real rows for 1,000 and 10,000 Works, increments citation counts, replays a parent UPSERT plus relationship replacement three times, verifies value idempotency, witnesses 100 tombstones, and rolls the transaction back. Baseline values and table counts are checked afterwards. These are **synthetic staged apply measurements**, excluding extraction, staging, COMMIT/fsync, real snapshot reconciliation, concurrency and full deletion/merge handling. They do not establish production update throughput. Incoming references owned by unaffected Works remain.','', '| Changed Works | Child rows staged, total | First apply native s | Replay native s | Value-idempotent |','|---:|---:|---:|---|---|']
 for p in sorted((HERE/'results/update-probes').glob('update-*.json')):
  if 'telemetry' in p.name:continue
  v=json.loads(p.read_text());ts=[r['native_statement_execution_seconds'] for r in v['runs']];lines.append(f"| {v['batch_works']:,} | {sum(v['staged_rows'].values())-v['batch_works']:,} | {ts[0]:.3f} | {ts[1]:.3f} / {ts[2]:.3f} | Yes |")
 lines += ['', 'Initial loading can therefore be expressed as a modest set of SQL projections rather than a bespoke parser. Incremental sync has more bookkeeping than an append-only import, particularly replacing nested relationships, reconciling deletions/merges and keeping checkpoints. PostgreSQL provides transactional UPSERT and atomic relationship replacement, but index maintenance, WAL and vacuum work remain real costs; the rolled-back probe deliberately does not estimate all of them.','', '## Evidence and limits','', '- [Historical ClickHouse/Athena report](superpowers/2026-08-05-single-user-resource-benchmark-results.md) and [field coverage](openalex-field-inventory.md).','- Full local evidence under `~/work/data/openalex-postgres-20261108/`; archived summaries, plans, settings, hashes and harness are in [the result directory](../results/postgres-local-2026-11-08/). Passwords, PGDATA and temporary files are excluded.','- The user explicitly requested no Claude Code validation for PostgreSQL. Correctness here is backed by the real PostgreSQL executions, complete typed output comparisons and archived plans. No Claude validation was invoked for this work.','- No full corpus was loaded, no PostgreSQL cluster was tested, and no full-corpus latency or RAM requirement is inferred. A Docker bind-mount benchmark on this laptop does not establish an EC2 configuration.','']
 (WT/'docs/postgres-local-benchmark.md').write_text('\n'.join(lines).replace('–',' to '))
